<?php
if(!defined('REDFOX_SKIP_BOTAPI_ROUTER'))define('REDFOX_SKIP_BOTAPI_ROUTER',true);require_once __DIR__.'/../lib/Security.php';redfox_secure_session_start();require_once __DIR__.'/../config.php';require_once __DIR__.'/../lib/SecureUpdater.php';require_once __DIR__.'/../lib/Certification.php';require_once __DIR__.'/lib/icons.php';$q=$pdo->prepare('SELECT * FROM admin WHERE username=? LIMIT 1');$q->execute([$_SESSION['user']??'']);$admin=$q->fetch(PDO::FETCH_ASSOC);if(!$admin){header('Location:login.php');exit;}if(($admin['rule']??'')!=='administrator'){http_response_code(403);exit;}$flash='';$ft='success';$panelTest=null;
if(isset($_GET['download'])){$id=(int)$_GET['download'];$q=$pdo->prepare('SELECT report_json FROM certification_runs WHERE id=?');$q->execute([$id]);$raw=$q->fetchColumn();if($raw===false){http_response_code(404);exit;}header('Content-Type:application/json');header('Content-Disposition:attachment;filename="redfox-certification-'.$id.'.json"');echo$raw;exit;}
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){$act=(string)($_POST['action']??'');try{if($act==='run'){$cert=new RedFoxCertification($pdo,dirname(__DIR__));$report=$cert->run();$pdo->prepare('INSERT INTO certification_runs(status,score,report_json,created_by,created_at) VALUES(?,?,?,?,?)')->execute([$report['status'],$report['score'],json_encode($report,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$admin['username'],time()]);$flash='گزارش Pre-Certification ساخته شد: '.$report['score'].'٪';}elseif($act==='save_test'){$code=trim((string)($_POST['panel_code']??''));$username=trim((string)($_POST['test_username']??''));if(!preg_match('/^[A-Za-z0-9_.@-]{1,191}$/',$code)||!preg_match('/^[A-Za-z0-9_.@-]{3,191}$/',$username))throw new RuntimeException('کد پنل یا نام تست نامعتبر است.');$pdo->prepare('INSERT INTO panel_test_accounts(panel_code,test_username,updated_at) VALUES(?,?,?) ON DUPLICATE KEY UPDATE test_username=VALUES(test_username),updated_at=VALUES(updated_at)')->execute([$code,$username,time()]);$flash='اکانت تست ذخیره شد.';}elseif($act==='test_panel'){$code=trim((string)($_POST['panel_code']??''));$q=$pdo->prepare('SELECT t.test_username,p.name_panel FROM panel_test_accounts t JOIN marzban_panel p ON p.code_panel=t.panel_code WHERE t.panel_code=?');$q->execute([$code]);$testRow=$q->fetch(PDO::FETCH_ASSOC);$username=(string)($testRow['test_username']??'');if($username==='')throw new RuntimeException('ابتدا نام کاربری تست را ذخیره کنید.');require_once __DIR__.'/../panels.php';$m=new ManagePanel();$start=microtime(true);$r=$m->DataUser((string)$testRow['name_panel'],$username);$ms=(int)round((microtime(true)-$start)*1000);$ok=is_array($r)&&!in_array((string)($r['status']??''),['Unsuccessful','error','failed'],true);$panelTest=['ok'=>$ok,'code'=>$code,'username'=>$username,'status'=>(string)($r['status']??'unknown'),'latency_ms'=>$ms,'has_limit'=>isset($r['data_limit']),'has_expire'=>isset($r['expire'])];$flash=$ok?'تست Read-only پنل موفق بود.':'تست پنل ناموفق بود.';$ft=$ok?'success':'error';}}catch(Throwable$e){$flash=redfox_public_exception($e, 'panel/certification.php');$ft='error';}}
try{$runs=$pdo->query('SELECT id,status,score,created_by,created_at FROM certification_runs ORDER BY id DESC LIMIT 30')->fetchAll(PDO::FETCH_ASSOC);$panels=$pdo->query("SELECT p.code_panel,p.name_panel,p.type,p.status,t.test_username,t.updated_at FROM marzban_panel p LEFT JOIN panel_test_accounts t ON t.panel_code=p.code_panel ORDER BY p.id")->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable$e){$runs=$panels=[];$flash='Migration 009 اجرا نشده است.';$ft='error';}
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pre-Certification</title><link rel="stylesheet" href="css/theme.css"><style>.success{color:var(--color-success)}.error{color:var(--color-danger)}code{font-size:11px}</style></head><body><section id="container"><?php include'header.php';?><section id="main-content"><div class="wrapper"><div class="page-head"><h1 class="page-head__title">Pre-Certification هاست</h1><div class="page-head__sub">بررسی Read-only محیط، دیتابیس، پنل‌ها، درگاه‌ها، Cron و صف‌های تطبیق</div></div><?php if($flash):?><div class="card <?=$ft?>"><?=htmlspecialchars($flash)?></div><?php endif;?><?php if($panelTest):?><div class="card"><pre><?=htmlspecialchars(json_encode($panelTest,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))?></pre></div><?php endif;?><div class="card"><form method="post"><input type="hidden" name="action" value="run"><button class="btn btn-primary">اجرای گزارش Pre-Certification</button></form><p>این گزارش تراکنش واقعی یا تغییر کاربر VPN انجام نمی‌دهد؛ برای Certification نهایی همچنان پرداخت و سرویس آزمایشی واقعی لازم است.</p></div><div class="card"><h2>تست Read-only کانکتورها</h2><div class="table-wrap"><table class="app-table"><tr><th>پنل</th><th>نوع</th><th>اکانت تست موجود</th><th>تنظیم</th><th>تست</th></tr><?php foreach($panels as$p):?><tr><td><?=htmlspecialchars($p['name_panel'])?><br><code><?=htmlspecialchars($p['code_panel'])?></code></td><td><?=htmlspecialchars($p['type'])?></td><td><?=htmlspecialchars($p['test_username']??'—')?></td><td><form method="post"><input type="hidden" name="action" value="save_test"><input type="hidden" name="panel_code" value="<?=htmlspecialchars($p['code_panel'])?>"><input name="test_username" value="<?=htmlspecialchars($p['test_username']??'')?>" placeholder="username موجود در پنل" required><button class="btn btn-sm">ذخیره</button></form></td><td><form method="post"><input type="hidden" name="action" value="test_panel"><input type="hidden" name="panel_code" value="<?=htmlspecialchars($p['code_panel'])?>"><button class="btn btn-sm btn-primary">DataUser Read-only</button></form></td></tr><?php endforeach;?></table></div></div><div class="card"><h2>گزارش‌ها</h2><table class="app-table"><tr><th>زمان</th><th>وضعیت</th><th>امتیاز</th><th>عامل</th><th></th></tr><?php foreach($runs as$r):?><tr><td><?=date('Y/m/d H:i',(int)$r['created_at'])?></td><td><?=$r['status']?></td><td><?=$r['score']?>٪</td><td><?=htmlspecialchars($r['created_by'])?></td><td><a class="btn btn-sm" href="?download=<?=$r['id']?>">JSON</a></td></tr><?php endforeach;?></table></div></div></section></section></body></html>
